using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
using RenoDXMfgUnlocker;
internal static class Rc10Checks
{
    public static IEnumerable<(string Name,Action Run)> All(){
        yield return("rc10 actual Restore click opens scoped confirmation and Cancel leaves files unchanged",Confirmation);
        yield return("rc10 Intel cache presence cannot claim session verification",Cache);
        yield return("rc10 changed labels and complete settings footer translate in six languages",Localization);
        yield return("rc10 real diagnostic hierarchy details log search and language state",Diagnostics);
        yield return("rc10 profile summary tooltip bounds and disabled settings remain readable",Profile);
        yield return("rc10 language changes preserve selected EXE and unsaved setting presentation",SettingsState);
    }
    private const BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
    private static void Check(bool value,string text){if(!value)throw new Exception(text);}
    private static string Temp(){var path=Path.Combine(AppContext.BaseDirectory,"Rc10Checks",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);return path;}
    private static MainWindow Shell(){var main=new MainWindow();main.Loaded-=typeof(MainWindow).GetMethod("Window_Loaded",Flags)!.CreateDelegate<RoutedEventHandler>(main);main.Show();return main;}
    private static IEnumerable<DependencyObject> Tree(DependencyObject root){for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);yield return child;foreach(var nested in Tree(child))yield return nested;}}
    private static void Drain(Window window){window.UpdateLayout();Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.ApplicationIdle);window.UpdateLayout();}
    private static Button Button(DependencyObject root,string text)=>Tree(root).OfType<Button>().Single(b=>LocalizedPresentation.SourceText(b,ContentControl.ContentProperty)==text);
    private static void Confirmation()=>WpfCheckHost.Run(()=>{
        LocalizedPresentation.Language.SetCulture("en-US",false);var main=Shell();var root=Temp();var exe=Path.Combine(root,"own-confirmation.exe");File.WriteAllText(exe,"never launched");var file=Path.Combine(root,"a.dll");File.WriteAllText(file,"original");var service=new BackupRestoreService(Temp());var tx=service.ExecuteAsync(root,[new("a.dll",[1,2,3])]).GetAwaiter().GetResult();var before=File.ReadAllBytes(file);typeof(MainWindow).GetField("selectedExe",Flags)!.SetValue(main,exe);typeof(MainWindow).GetField("selectedGameRoot",Flags)!.SetValue(main,root);
        var stage=0;Exception? failure=null;Window? recovery=null;var deadline=DateTime.UtcNow.AddSeconds(8);var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(30)};
        timer.Tick+=(_,_)=>{try{
            if(DateTime.UtcNow>deadline)throw new TimeoutException("Restore confirmation UI timed out");
            recovery??=main.OwnedWindows.OfType<Window>().FirstOrDefault(w=>w.Title=="Component transaction recovery");if(recovery is null)return;
            if(stage==0){var list=Tree(recovery).OfType<ListBox>().Single();if(list.Items.Count==0)return;list.SelectedIndex=0;stage=1;}
            else if(stage==1){var restore=Button(recovery,"Restore selected transaction");if(!restore.IsEnabled)return;stage=2;main.Dispatcher.BeginInvoke(new Action(()=>restore.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent))));}
            else if(stage==2){var confirm=recovery.OwnedWindows.OfType<Window>().FirstOrDefault();if(confirm is null)return;var text=string.Join("\n",Tree(confirm).OfType<TextBlock>().Select(t=>t.Text));Check(text.Contains(root)&&text.Contains(tx.TransactionId)&&text.Contains("Affected files: 1"),"Confirmation lacks exact scope");Check(File.ReadAllBytes(file).SequenceEqual(before),"Restore wrote before confirmation");stage=3;Button(confirm,"Cancel").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));}
            else {Check(File.ReadAllBytes(file).SequenceEqual(before)&&service.PreviewRestore(root,tx.TransactionId).CanRestore,"Cancel changed files or transaction");timer.Stop();recovery.Close();}
        }catch(Exception ex){failure=ex;timer.Stop();if(recovery is not null){foreach(Window child in recovery.OwnedWindows)child.Close();recovery.Close();}}};
        try{timer.Start();var task=(Task)typeof(MainWindow).GetMethod("ShowRestoreManagerAsync",Flags)!.Invoke(main,[root,service,main])!;while(!task.IsCompleted)Drain(main);task.GetAwaiter().GetResult();if(failure is not null)throw failure;Check(stage==3,"No confirmation was observed");}finally{timer.Stop();main.Close();}
    });
    private static void Cache(){var path=Temp();Check(IntelCachePresentation.Status(path,false,false)=="No local cache","Missing cache wrong");File.WriteAllText(Path.Combine(path,IntelRuntimeService.Assets[0].Name),"unverified bytes");Check(IntelCachePresentation.Status(path,false,false)=="Cached, verification pending","Presence became verified");Check(IntelCachePresentation.Status(path,true,false)=="Verified in current session","Verified session not shown");Check(IntelCachePresentation.Status(path,false,true)=="Failed verification","Failed state lost");}
    private static void Localization(){var language=new UiLocalization();var version="1.7.0.0";var footer=$"MFG Unlock {version} · saved configuration values only. Changes apply after restarting the game. Current runtime state cannot be read here.";foreach(var culture in UiLocalization.Cultures.Where(c=>c!="en-US")){language.SetCulture(culture,false);foreach(var key in new[]{"Overview","Logs","Warnings","Restore available","Restore original","Action","Destination state","Backup integrity","Matches installed SHA-256","Verified SHA-256","Needs Review","Profile details","Unsaved changes","Files: {0}","Transaction: {0}"})Check(language.GetCatalog(culture).ContainsKey(key)&&(language.Translate(key)!=key||(culture=="fr-FR"&&key=="Action")),"English fallback: "+culture+" / "+key);var translated=language.Translate(footer);Check(translated.Contains(version)&&!translated.Contains("saved configuration values"),"Footer partly English or version changed");}}
    private static void Diagnostics()=>WpfCheckHost.Run(()=>{
        var main=Shell();string? opened=null;var panel=new RuntimeDiagnosticsPanel((_,text)=>opened=text);var report=new RuntimeDiagnosticReport(["DLL installed: Not verified","Runtime loaded: Not verified","NVIDIA Dynamic MFG: active Not verified"],["Disk · own.dll · 1.2.3.4\nC:\\isolated\\bin\\own.dll\nSHA-256: abc","Previous / unverified session · 2026-01-01T00:00:00Z\nOld.log","Mapped module reported · old.dll","Current process session matched · 2026-10-31T00:00:00Z\nNow.log","Mapped module reported · now.dll"],[],[new("Own.log","alpha NEEDLE omega",DateTimeOffset.UtcNow)]);panel.Render(report);var dialog=main.CreateInfoDialog("Runtime Diagnostics",panel);var trace=new StringWriter();var listener=new System.Diagnostics.TextWriterTraceListener(trace);System.Diagnostics.PresentationTraceSources.DataBindingSource.Listeners.Add(listener);
        try{dialog.Show();Drain(dialog);Button(panel,"Installed Components").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Drain(dialog);Check(!Tree(panel).OfType<TextBlock>().Any(t=>t.Text.Contains("SHA-256")),"Hash wall remains in compact component view");Button(panel,"Details").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Check(opened==report.Evidence[0],"Component Details lost original path/hash evidence");Button(panel,"Session / Loaded Modules").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Drain(dialog);Check(Tree(panel).OfType<TextBlock>().Any(t=>LocalizedPresentation.SourceText(t,TextBlock.TextProperty)=="Historical / unconfirmed session")&&Tree(panel).OfType<TextBlock>().Any(t=>LocalizedPresentation.SourceText(t,TextBlock.TextProperty)=="Confirmed current session"),"Session provenance collapsed");Button(panel,"Logs").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Drain(dialog);var query=Tree(panel).OfType<TextBox>().Single(t=>!t.IsReadOnly);query.Text="NEEDLE";Button(panel,"Find next").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Check(Tree(panel).OfType<TextBox>().Single(t=>t.IsReadOnly).SelectedText=="NEEDLE","Raw-log search failed");foreach(var culture in UiLocalization.Cultures){LocalizedPresentation.Language.SetCulture(culture,false);Drain(dialog);Check(query.Text=="NEEDLE"&&Tree(panel).OfType<TextBox>().Single(t=>t.IsReadOnly).Text==report.Logs![0].Text,"Language switch changed query/raw log");Check(Button(panel,"Overview").Content as string==LocalizedPresentation.Language.Lookup("Overview"),"Tab not localized");}listener.Flush();Check(!trace.ToString().Contains("Error:"),"Binding errors: "+trace);}finally{System.Diagnostics.PresentationTraceSources.DataBindingSource.Listeners.Remove(listener);dialog.Close();main.Close();}
    });
    private static void Profile()=>WpfCheckHost.Run(()=>{var main=Shell();try{typeof(MainWindow).GetMethod("ApplyCompatibilityAssessment",Flags)!.Invoke(main,[null]);Drain(main);var summary=(TextBlock)main.FindName("NvidiaCompatibilityDetailsText");Check(summary.Text.Length<600&&((TextBlock)main.FindName("NvidiaCompatibilityStatusText")).ToolTip as string==LocalizedPresentation.Language.Lookup("Open Profile details for full compatibility evidence."),"Evidence document remains in hover");Check(Tree((FrameworkElement)main.FindName("NvidiaGameContext")).OfType<Button>().Any(b=>LocalizedPresentation.SourceText(b,ContentControl.ContentProperty)=="Profile details"),"Keyboard-accessible details missing");var tooltip=new ToolTip {Content=new string('x',1000),Style=(Style)main.FindResource(typeof(ToolTip))};Check(tooltip.MaxWidth<=420&&tooltip.MaxHeight<=170&&tooltip.Background is SolidColorBrush brush&&brush.Color.R<80,"Tooltip native white or unbounded");Check(((TextBlock)main.FindName("MfgRestartStatusText")).Text==LocalizedPresentation.Language.Lookup("Changes apply after restarting the game."),"Unedited page claims pending restart");}finally{main.Close();}});
    private static void SettingsState()=>WpfCheckHost.Run(()=>{
        var main=Shell();var type=typeof(MainWindow);try{
            var root=Temp();var exe=Path.Combine(root,"own-ui.exe");File.WriteAllText(exe,"never launched");type.GetField("selectedExe",Flags)!.SetValue(main,exe);type.GetField("selectedGameRoot",Flags)!.SetValue(main,root);
            type.GetMethod("SetPage",Flags)!.Invoke(main,[Enum.Parse(type.GetNestedType("AppPage",BindingFlags.NonPublic)!,"MfgSettings")]);
            var rowType=type.GetNestedType("MfgUnlockSettingRow",BindingFlags.NonPublic)!;var definition=new MfgUnlockSettingsService().Definitions[0];
            // Presentation-only saved/proposed values; no addon identity or write permission is granted.
            var editable=Activator.CreateInstance(rowType,[definition,"1","0",true,(Action)(()=>{})])!;
            var disabled=Activator.CreateInstance(rowType,[definition,"1","1",false,(Action)(()=>{})])!;
            var items=(ItemsControl)main.FindName("MfgSettingsItemsControl");items.ItemsSource=new[]{editable,disabled};Drain(main);
            var combos=Tree(items).OfType<ComboBox>().ToArray();Check(combos.Length==2&&combos[0].IsEnabled&&!combos[1].IsEnabled&&combos[1].Opacity<.6,"Read-only field looks editable");
            foreach(var culture in UiLocalization.Cultures){LocalizedPresentation.Language.SetCulture(culture,false);Drain(main);Check((string?)rowType.GetProperty("ProposedValue")!.GetValue(editable)=="0"&&type.GetField("selectedExe",Flags)!.GetValue(main) as string==exe,"Language changed pending setting or game EXE");}
            Check(!File.Exists(Path.Combine(root,"ReShade.ini")),"Display test wrote settings");
        }finally{main.Close();}
    });
}
